"""Generate the API reference pages from public ``__all__`` exports.

Run ``.venv/bin/python scripts/gen_reference.py`` after changing a public
module's exports or a docstring; ``tests/test_reference.py`` fails when the
committed pages drift from this output.
"""

from __future__ import annotations

import importlib
from dataclasses import dataclass
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "docs" / "reference"

_GENERATED_NOTE = (
    "<!-- Generated by scripts/gen_reference.py; edit docstrings, not this file. -->"
)


@dataclass(frozen=True)
class Page:
    slug: str
    title: str
    intro: str
    modules: tuple[str, ...] = ()
    symbols: tuple[str, ...] = ()
    order: tuple[tuple[str, str], ...] = ()
    overrides: tuple[tuple[str, str], ...] = ()


