def _module_name(module: str, name: str) -> str:
    return f"{module}.{name}"


def _group_label(
    module_name: str,
    order: tuple[tuple[str, str], ...],
    modules: tuple[str, ...],
) -> str:
    for prefix, label in order:
        if module_name == prefix or module_name.startswith(prefix + "."):
            return label
    if any(
        module_name == module or module_name.startswith(module + ".")
        for module in modules
    ):
        leaf = module_name.rsplit(".", 1)[-1]
        return leaf.replace("_", " ").title()
    return "Constants and aliases"


def _symbols(page: Page) -> list[tuple[str, str, str]]:
    """``(target, display_name, group)`` for one page, in stable order."""
    if page.symbols:
        return [
            (target, target.rsplit(".", 1)[-1], "Sources") for target in page.symbols
        ]
    collected: list[tuple[str, str, str]] = []
    for module_name in page.modules:
        module = importlib.import_module(module_name)
        names: list[str] = list(getattr(module, "__all__", ()))
        overrides = dict(page.overrides)
        for name in names:
            obj: Any = getattr(module, name)
            defining = str(getattr(obj, "__module__", module_name))
            collected.append(
                (
                    _module_name(module_name, name),
                    name,
                    overrides.get(name)
                    or _group_label(defining, page.order, page.modules),
                )
            )
    return collected


def render_page(page: Page) -> str:
    symbols = _symbols(page)
    groups: dict[str, list[tuple[str, str]]] = {}
    for target, name, group in symbols:
        groups.setdefault(group, []).append((target, name))

    lines = [
        _GENERATED_NOTE,
        "",
        f"# {page.title}",
        "",
        page.intro,
        "",
    ]
    ordered = list(page.order)
    for label in dict.fromkeys(group for _, _, group in symbols):
        if label not in {name for _, name in ordered}:
            ordered.append((label, label))
    for _, label in ordered:
        entries = groups.get(label)
        if not entries:
            continue
        lines += [f"## {label}", ""]
        for target, name in entries:
            lines += [f"### `{name}`", "", f"::: {target}", ""]
    return "\n".join(lines).rstrip() + "\n"


def render_index() -> str:
    lines = [
        _GENERATED_NOTE,
        "",
        "# Auto-generated reference",
        "",
        "These pages are rendered from the source docstrings — signatures, type",
        "hints and the actual rationale text, not a hand-maintained copy. If a",
        "page and a docstring disagree, the docstring is the truth.",
        "",
        "The stability contract is in [API](../en/api.md); narrative guides are",
        "under **Build** in the navigation.",
        "",
        "| Area | Page |",
        "| --- | --- |",
        "| Core runtime, artifacts, steps | [Core](core.md) |",
        "| Ingestion, retrieval, MMR, DocStore | [Knowledge](knowledge.md) |",
        "| Metrics, datasets, judges | [Evaluation](eval.md) |",
        "| Query-time sources | [Sources](sources.md) |",
        "| Chat/embedding/image providers | [Providers](providers.md) |",
        "| Ready-made agent shapes | [Recipes](recipes.md) |",
        "| Traces, spans, stores | [Tracing](tracing.md) |",
        "",
    ]
    return "\n".join(lines)


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    for page in PAGES:
        (OUT / f"{page.slug}.md").write_text(render_page(page), encoding="utf-8")
    (OUT / "index.md").write_text(render_index(), encoding="utf-8")


if __name__ == "__main__":
    main()
